import{_ as n,a as t,b as i,c as r,d as s,e as d}from"./chunks/files-search.DHVpDIe3.js";import{_ as a,o as l,c as g,a3 as o}from"./chunks/framework.BlfGB29P.js";const S=JSON.parse('{"title":"Editor und Tastenkombinationen","description":"","frontmatter":{"title":"Editor und Tastenkombinationen"},"headers":[],"relativePath":"projects/grafik-visual-studio/editor.md","filePath":"projects/grafik-visual-studio/editor.md","lastUpdated":1792684236000}'),u={name:"projects/grafik-visual-studio/editor.md"};function h(c,e,b,p,k,m){return l(),g("div",null,[...e[0]||(e[0]=[o('<h1 id="editor-und-tastenkombinationen" tabindex="-1">Editor und Tastenkombinationen <a class="header-anchor" href="#editor-und-tastenkombinationen" aria-label="Permalink to &quot;Editor und Tastenkombinationen&quot;">​</a></h1><p>Ab <strong>0.1.296</strong> gibt es eine Projekt-/Widget-Sprache DE/EN/FR für die verbleibenden Pakete und Anzeigen sowie optionale <a href="./ha-quellen-climate">HA-Quellen, Einheiten und Climate-Bedienelemente</a>. Die allgemeine Studio-Oberfläche bleibt DE/EN; alte Einstellungen bleiben gültig.</p><p>Ab <strong>Studio 0.1.295</strong> sind zusätzliche <a href="/projects/grafik-visual-studio/interaktiv">Universal-Funktionen, radiale Farbverläufe und größere Material-Icons</a> verfügbar. Einstellungen und bisheriges Tasterverhalten bleiben erhalten; neue Optionen sind bewusst wählbar.</p><p>Ab <strong>Studio 0.1.294</strong> füllen die Vorschaubilder aller elf <strong>Interaktiv-Widgets</strong> den vorhandenen Rahmen in Seitenleiste und Widget-Auswahl, passend zu Hell/Dunkel. Einstellungen und Runtime-Verhalten bleiben erhalten. Der <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/inventwo-interactive-audit-2026-10-12.md" target="_blank" rel="noreferrer">Quellcodevergleich mit Inventwo VIS-2 1.10.0</a> dokumentiert die Unterschiede: Besonders Universal fehlen noch zusätzliche Aktionen/Inhalte und dem radialen Schieberegler Farbverläufe. Vollständige 1:1-Gleichheit ist damit nicht erreicht.</p><p>Ab <strong>Studio 0.1.293</strong> sind die <a href="/projects/grafik-visual-studio/basic">Basic-Ergänzungen aus dem VIS-2-Vergleich</a> verfügbar, einschließlich separat wählbarer DE/EN/FR-Eigenschaften. Alte Widget-Einstellungen bleiben erhalten.</p><p>Ab <strong>Studio 0.1.291</strong> funktionieren <strong>Strg+C</strong> (Kopieren), <strong>Strg+X</strong> (Ausschneiden) und <strong>Strg+V</strong> (Einfügen) für einzelne und mehrere ausgewählte Widgets. Auf macOS gilt entsprechend Cmd. Sie verwenden dieselbe interne Widget-Zwischenablage wie Toolbar und Kontextmenü; eingefügte Widgets erhalten neue IDs, ihre Werte bleiben erhalten. Rückgängig kann Ausschneiden und Einfügen zurücknehmen. In Textfeldern bleiben die normalen Text-Tastenkürzel aktiv; offene Dialoge und Runtime lösen keine Widget-Aktionen aus.</p><p>Ab <strong>Studio 0.1.290</strong> öffnet <strong>Entf</strong> für ausgewählte Widgets denselben Löschdialog wie der Papierkorb. Das gilt auch bei Mehrfachauswahl. Abbrechen oder Escape behält die Widgets; nach bestätigtem Löschen kann Rückgängig sie wiederherstellen. Die freiwillige Unterdrückung weiterer Fragen für fünf Minuten gilt auch für Entf. In Textfeldern, offenen Dialogen und der Runtime löscht die Taste keine Widgets; gedrückt gehaltene Tasten lösen keine weiteren Abfragen aus.</p><h2 id="widgets-nur-in-der-runtime-ausblenden" tabindex="-1">Widgets nur in der Runtime ausblenden <a class="header-anchor" href="#widgets-nur-in-der-runtime-ausblenden" aria-label="Permalink to &quot;Widgets nur in der Runtime ausblenden&quot;">​</a></h2><p>Ab <strong>Studio 0.1.287</strong> gibt es für <strong>alle Widgets</strong> direkt oben im Reiter <strong>WIDGET</strong> die Checkbox <strong>In Runtime verstecken</strong>. Haken setzen und das Projekt speichern: Das Widget bleibt im Editor sichtbar, wird aber in der Runtime ausgeblendet. Berechnungen und Werteübergaben bleiben aktiv, beispielsweise von einem versteckten Number-Widget zu Math. Die Checkbox funktioniert unabhängig vom Z-Index. Ohne Haken gilt wieder die normale Sichtbarkeit; spezielle Datenfluss-Widgets bleiben grundsätzlich verborgen. Versteckte Bedienelemente können in der Runtime nicht angeklickt werden.</p><p>Ab <strong>Studio 0.1.286</strong> blendet ein expliziter <strong>Z-Index −100 oder kleiner</strong> jeden Widgettyp in der Runtime aus. Im Editor bleibt das Widget sichtbar und bearbeitbar. Berechnungen und Datenfluss bleiben aktiv; so lassen sich Number-Widgets, MathBoxen und ihre Leitungen als unsichtbare Verarbeitungskette nutzen. Bei −99 oder höher greift diese spezielle Ausblendregel nicht. Ein verborgenes Bedienelement lässt sich in der Runtime nicht anklicken.</p><h2 id="seiten-tabs" tabindex="-1">Seiten-Tabs <a class="header-anchor" href="#seiten-tabs" aria-label="Permalink to &quot;Seiten-Tabs&quot;">​</a></h2><p>Ab <strong>Studio 0.1.256</strong> erscheinen die Projektseiten als kompakte <strong>Tabs direkt über der Arbeitsfläche</strong>, zwischen Widget-Palette und Eigenschaften. Ein Klick wechselt die Seite; die aktive Seite ist farbig markiert. Viele Seiten scrollen horizontal, lange Namen werden gekürzt und stehen vollständig im Tooltip. In der Runtime ausgeblendete Seiten bleiben im Editor erreichbar und haben einen gestrichelten Tab-Rand.</p><p><img src="'+n+'" alt="Projektseiten als Tabs über der Editorfläche"></p><p>Mit Fokus auf einem Tab wechseln <strong>Pfeil links/rechts</strong> zur benachbarten Seite, <strong>Pos1/Ende</strong> zur ersten/letzten. Ungespeicherte Widgetänderungen bleiben beim Wechsel im Projekt; die Widgetauswahl und offene Widget-Aktionen werden zurückgesetzt. Seitennamen und Reihenfolge folgen dem bestehenden <strong>Seiten</strong>-Menü. Anlegen, Umbenennen, Duplizieren, Sichtbarkeit und Löschen bleiben dort. Die Tabs sind eine Editorhilfe; die Runtime verwendet weiterhin ihre bisherige Seitennavigation.</p><h2 id="einstieg" tabindex="-1">Einstieg <a class="header-anchor" href="#einstieg" aria-label="Permalink to &quot;Einstieg&quot;">​</a></h2><p>Ab <strong>0.1.184</strong> unterscheiden Hintergrundfarben die Widget-Sets in der Palette: <strong>Interaktiv</strong> ist olivgrün, <strong>Spezial</strong> blau und <strong>Datenfluss</strong> violett. <strong>Basis</strong> behält seine bisherige Darstellung. Zusätzliche installierte Sets erhalten jeweils eine eigene Farbe. Die Farben gelten für die Auswahlknöpfe der Palette; die Gestaltung eingefügter Widgets bleibt unabhängig.</p><p>Ab <strong>0.1.185</strong> sind die Auswahlboxen aller Sets flacher: 34 statt 42 px Mindesthöhe, mit 32 × 26 px großen Vorschauen. Die Beschriftungen bleiben gut lesbar. <strong>Dashboard in widget</strong> erhält das Standard-Symbol <code>mdi:view-dashboard</code>.</p><p><img src="'+t+'" alt="Flachere Auswahlboxen der Widget-Palette"></p><p>Ab Studio <strong>0.1.115</strong> öffnet ein Rechtsklick auf ein Widget, eine Gruppenlasche oder die freie Editorfläche ein Kontextmenü: <strong>Auswählen</strong>, <strong>Gruppieren</strong>, <strong>Gruppierung aufheben</strong>, <strong>Gruppe bearbeiten</strong>, <strong>Kopieren</strong>, <strong>Ausschneiden</strong>, <strong>Einfügen</strong> und <strong>Löschen</strong>. <strong>Mehr</strong> enthält Duplizieren, Vorder-/Hintergrund, Sperren/Entsperren, Rückgängig/Wiederholen und Widget-Import/Export. Nicht verfügbare Aktionen sind ausgegraut; Escape schließt das Menü, Pfeil hoch/runter navigiert darin. Auswählen bietet alle Widgets und die Widgets unter dem Mauszeiger.</p><p>Gruppen behalten die freien Positionen ihrer Mitglieder und werden beim Ziehen eines Mitglieds oder der Gruppenlasche gemeinsam bewegt. Sie werden im Projekt gespeichert; Kopien und Exporte mehrerer ausgewählter Widgets erhalten beim Einfügen beziehungsweise Import unabhängige Gruppen. <strong>Gruppe bearbeiten</strong> erlaubt einzelne Mitglieder zu bearbeiten; <strong>Gruppenbearbeitung beenden</strong> oder ein Klick auf die Gruppenlasche wechselt zurück zur gemeinsamen Auswahl. Gruppierung aufheben erhält Positionen und Größen. Rückgängig/Wiederholen gilt auch für Gruppierung und Bewegung. Gruppen sind flach; SVG-Verbindungslinien können nicht gruppiert werden, und Gruppen mit gesperrten Mitgliedern lassen sich nicht ziehen. Die Runtime zeigt weder Gruppenrahmen noch das Editormenü. Die Gruppierung erzeugt keine Tab-Inhalte und importiert keine VIS2-Widgets.</p><p>Lege im Menü <strong>Projekte</strong> ein Projekt an und wähle über <strong>Seiten</strong> eine Seite. Stelle die Seitengröße ein, verwende die linke <strong>Widget-Palette</strong> und füge ein Element aus der Palette ein. Mit <strong>Widgets suchen</strong> oben in der Palette filterst du die verfügbaren Widgets nach Name oder Typ; passende Gruppen öffnen sich während der Suche, ohne ihre bisherigen Klappzustände zu ändern. Ein Klick auf ein Widget wählt es aus; rechts erscheinen seine Eigenschaften. Über <strong>Runtime</strong> prüfst du die Ansicht. <strong>Speichern</strong> sichert manuell; unter <strong>Einstellungen → Allgemein</strong> lassen sich Auto-Save und dessen Verzögerung ändern. Unter <strong>Widget-Pakete</strong> kannst du ab Version 0.1.80 ein lokales <code>.wg.zip</code> installieren. Die erste Schnittstelle 0.1 unterstützt geprüfte Text-Widgets mit Eigenschaften; installierte Pakete erscheinen als eigenes Set in der Palette. Seit 0.1.83 dürfen Widget- und Paketbilder geprüfte SVG- oder PNG-Dateien sein; ohne eigenes Widget-Bild erscheint das integrierte SVG-Textsymbol. Das Entfernen ist gesperrt, wenn ein Paket-Widget in einem Projekt verwendet wird. Ab 0.1.82 installiert der Tab <strong>Tools</strong> lokale <code>.tp.zip</code>-Pakete. Das erste deklarative Tool zeigt eine Vorschau und ändert nach Bestätigung die Hintergrundfarbe der aktuellen Seite; <strong>Rückgängig</strong> kann die Änderung zurücknehmen. Auch Tool-Bilder dürfen SVG oder PNG sein; Studio-Buttons verwenden SVG-Symbole. GitHub-Installation und Updates folgen später.</p><p>In der Widget-Auswahl der oberen Leiste kannst du mehrere Widgets markieren oder die Auswahl aufheben. Die Aktionsleiste bietet Ausschneiden, Kopieren, Einfügen, Duplizieren, Löschen und bis zu 50 Schritte Rückgängig/Wiederholen. Die zehn Ausrichtungsaktionen arbeiten mit mehreren ausgewählten normalen Widgets; das erste ausgewählte Widget ist die Referenz. Bei <strong>Breite</strong> und <strong>Höhe</strong> öffnet langes Drücken (etwa 0,6 Sekunden) eine Eingabe für den gewünschten Pixelwert.</p><p>Die Runtime zentriert eine Seite, wenn sie vollständig ins Browserfenster passt. Bei größeren Seiten beginnt sie links oben; horizontale und vertikale Scrollbalken machen die ganze Seite erreichbar, ohne Widget-Koordinaten zu verändern.</p><h2 id="widget-auswahl-kopieren-und-loschen" tabindex="-1">Widget-Auswahl, Kopieren und Löschen <a class="header-anchor" href="#widget-auswahl-kopieren-und-loschen" aria-label="Permalink to &quot;Widget-Auswahl, Kopieren und Löschen&quot;">​</a></h2><p>Ab <strong>Studio 0.1.257</strong> werden die Toolbar-Icons für <strong>Löschen</strong>, <strong>Kopieren</strong> und <strong>Ausschneiden</strong> direkt mit der Widgetauswahl aktiviert. Ohne ausgewählte Widgets sind diese Aktionen ausgegraut; das gilt auch beim Seitenwechsel. Die Löschbestätigung und Rückgängig bleiben verfügbar.</p><p><img src="'+i+'" alt="Widget-Auswahlliste mit zehn sichtbaren Einträgen"></p><p>Ab Studio <strong>0.1.196</strong> bietet die Liste Platz für zehn kompakte Einträge. Weitere Einträge sind innerhalb der Liste scrollbar; die Aktionen oben und unten bleiben sichtbar. Bei weniger Einträgen bleibt das Menü kürzer. Auf kleinen Bildschirmen richtet sich die Anzahl sichtbarer Zeilen nach der verfügbaren Höhe.</p><p>Die angehakten Zeilen wählen dieselben Widgets auf der Arbeitsfläche aus. Die Liste bleibt davor sichtbar; <strong>Kopieren</strong> und <strong>Löschen</strong> betreffen alle angehakten Widgets.</p><p><img src="'+r+'" alt="Mehrere eingefügte Widgets gemeinsam verschoben"></p><p>Ziehe eines der ausgewählten Widgets, um die gesamte Auswahl zu verschieben, auch nach Kopieren und Einfügen. Ausgewählte Verbindungen und Zwischenpunkte bewegen sich mit; gesperrte Widgets verhindern das gemeinsame Verschieben. Rückgängig nimmt den Zug als einen Schritt zurück.</p><p><img src="'+s+'" alt="Löschbestätigung mit fünf Minuten Unterdrückung"></p><p><strong>Abbrechen</strong> oder Escape beendet das Löschen. Das Häkchen unterdrückt weitere Fragen für fünf Minuten in dieser Editorsitzung. Gelöschte Widgets lassen sich weiterhin mit Rückgängig wiederherstellen.</p><h2 id="dateien-und-bildauswahl" tabindex="-1">Dateien und Bildauswahl <a class="header-anchor" href="#dateien-und-bildauswahl" aria-label="Permalink to &quot;Dateien und Bildauswahl&quot;">​</a></h2><p><img src="'+d+'" alt="Dateisuche unterhalb des Studio-Stammordners"></p><p>Der Stammordner ist <strong>/config/www/studio</strong>. Studio legt ihn nach Möglichkeit an; fehlende Schreibrechte werden gemeldet. Auch die Bildauswahl der Widgets verwendet diesen Ordner; öffentliche Pfade beginnen mit <strong>/local/studio/</strong>. Die Suche berücksichtigt alle Unterordner sowie Dateinamen und Pfade ohne Beachtung der Groß-/Kleinschreibung. Ein leeres Suchfeld zeigt wieder den geöffneten Ordner. Bilder einschließlich GIF lassen sich auswählen. Der Wechsel zum übergeordneten Ordner bleibt innerhalb dieses Stammordners.</p><h2 id="sprache-der-oberflache" tabindex="-1">Sprache der Oberfläche <a class="header-anchor" href="#sprache-der-oberflache" aria-label="Permalink to &quot;Sprache der Oberfläche&quot;">​</a></h2><p>Öffne <strong>Einstellungen → Allgemein → Sprache → App-Sprache</strong>, wähle eine Option und klicke auf <strong>Speichern</strong>:</p><table tabindex="0"><thead><tr><th>Auswahl</th><th>Anzeige</th></tr></thead><tbody><tr><td><strong>Automatisch (Home Assistant)</strong></td><td>Deutsch, wenn Home Assistant auf Deutsch eingestellt ist; bei jeder anderen Sprache Englisch. Ist die HA-Sprache nicht erreichbar, gilt die Browsersprache mit demselben Deutsch-/Englisch-Rückfall.</td></tr><tr><td><strong>Deutsch</strong></td><td>Die Oberfläche bleibt auf Deutsch.</td></tr><tr><td><strong>English</strong></td><td>Die Oberfläche bleibt auf Englisch.</td></tr></tbody></table><p>Die Auswahl gilt nur in diesem Browser und bleibt nach einem Neuladen erhalten. Andere Benutzer und Browser behalten ihre eigene Wahl. Die Sprache ändert Oberflächentexte wie Menüs, Dialoge, Widget-Palette und Eigenschaften; selbst vergebene Projekt- und Widget-Namen sowie Widget-Inhalte werden nicht übersetzt.</p><h2 id="tastatur-und-maus" tabindex="-1">Tastatur und Maus <a class="header-anchor" href="#tastatur-und-maus" aria-label="Permalink to &quot;Tastatur und Maus&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aktion</th><th>Bedienung</th></tr></thead><tbody><tr><td>Rückgängig</td><td><code>Strg+Z</code> (macOS: <code>⌘+Z</code>)</td></tr><tr><td>Wiederholen</td><td><code>Strg+Y</code> oder <code>Strg+Umschalt+Z</code> (macOS: <code>⌘+Y</code> oder <code>⌘+Umschalt+Z</code>)</td></tr><tr><td>Widget zur Mehrfachauswahl hinzufügen oder daraus entfernen</td><td><code>Strg+Umschalt</code> gedrückt halten und das Widget anklicken</td></tr><tr><td>Freien Anfangs- oder Endpunkt einer Verbindung verschieben</td><td>Punkt mit der Maus ziehen; fokussierten Punkt mit den Pfeiltasten in 1-Pixel-Schritten bewegen</td></tr><tr><td>Linienpunkt schneller bewegen</td><td>Beim Drücken einer Pfeiltaste zusätzlich <code>Umschalt</code> halten: 10 Pixel pro Schritt</td></tr><tr><td>Angedockten Linienpunkt lösen</td><td><code>Strg</code> halten und den Punkt ziehen; mit <code>Strg</code> plus Pfeiltaste ebenfalls möglich</td></tr><tr><td>Ganze Verbindungslinie verschieben</td><td>Freie Linie ziehen; bei angedockter Linie <code>Alt</code> halten und ziehen. Bestehende Andockverbindungen werden dabei gelöst. Einzelne Punktgriffe bewegen keine Mehrfachauswahl; Ziehen startet ab 6 px Bewegung.</td></tr><tr><td>Zwischen- oder Sammelpunkt einfügen</td><td>Linie anklicken, „Zwischenpunkt“ oder „Sammelpunkt“ wählen und mit <strong>OK</strong> bestätigen</td></tr></tbody></table><p>Die Kürzel für Rückgängig/Wiederholen gelten, wenn der Fokus nicht in einem Eingabefeld, Textbereich oder Auswahlfeld liegt. Für Ausschneiden, Kopieren und Einfügen stehen Schaltflächen bereit; dafür sind derzeit keine globalen <code>Strg+X/C/V</code>-Kürzel eingerichtet.</p><h2 id="verbindungslinien-und-andockpunkte" tabindex="-1">Verbindungslinien und Andockpunkte <a class="header-anchor" href="#verbindungslinien-und-andockpunkte" aria-label="Permalink to &quot;Verbindungslinien und Andockpunkte&quot;">​</a></h2><p>Aktiviere <strong>Andockpunkte</strong> in den Eigenschaften eines Ziel-Widgets. Bei neuen Widgets sind alle Punkte aus. <strong>Alle Punkte</strong> schaltet die zwölf Positionen gemeinsam; einzelne Punkte können danach angepasst werden. Die Gruppen-Checkbox aktiviert oder deaktiviert den gesamten Bereich. Die Enden einer SVG-Verbindung lassen sich auf aktive Punkte ziehen. Ein Zwischenpunkt teilt den Pfad in weitere Segmente; nur ein ausdrücklich aktivierter <strong>Sammelpunkt</strong> kann von anderen Linien als Kopplung ausgewählt werden. Eine bloße Kreuzung verbindet Linien nicht. Für die Darstellung stehen unter anderem Linie, Zickzack-/Mehrpunktpfad, Farben, Dicke, Pfeilspitzen, Animation und z-index bereit.</p><h2 id="sichtbarkeit-und-filter" tabindex="-1">Sichtbarkeit und Filter <a class="header-anchor" href="#sichtbarkeit-und-filter" aria-label="Permalink to &quot;Sichtbarkeit und Filter&quot;">​</a></h2><p><strong>Generell</strong> und <strong>Sichtbarkeit</strong> sind bei jedem Widget vorhanden und standardmäßig deaktiviert. „Generell“ enthält unter anderem Name, Kommentar, CSS-Klasse, Filterwort und Sperre. Der Editor-Filter kann Widgets anhand des Filterworts ausblenden oder nur passende anzeigen. Die Sichtbarkeit kann in der Runtime einen Home-Assistant-Zustand mit Bedingung und Vergleichswert prüfen; die Gruppenauswertung ist noch offen.</p>',46)])])}const z=a(u,[["render",h]]);export{S as __pageData,z as default};
